import SwiftUI

/// The interface in the user's language, as Blender's Preferences ▸ Interface
/// ▸ Translation ▸ Language sets it.
///
/// Each language's table is `<lang>.lproj/Localizable.strings`, generated by
/// `scripts/l10n/build.py` from Blender's own catalog for that language (so a
/// Blender term reads exactly as it does in Blender) and the app's own
/// translations (`l10n/<lang>.json`). See l10n/TRANSLATING.md.
///
/// Most of the UI passes its text as `String` (menus, rows and buttons built
/// from data), so the lookup happens where text is shown: this module's
/// `Text(String)`, `Button(String)`, `Label`, `Toggle`, `Section`, `Menu`,
/// `Picker`, `TextField`, `.navigationTitle` and `.help` overloads below are
/// more specific than SwiftUI's generic `StringProtocol` ones, so every one of
/// those in this module translates without a change at the call site. Names
/// of data (objects, materials, files) are shown with `Text(verbatim:)`:
/// Blender never translates a datablock's name.
public enum Translation {
    /// The languages offered, with Blender's own names for them.
    public static let languages: [(code: String, name: String)] = [
        ("", "Automatic"),
        ("en", "English (US)"),
        ("zh-Hans", "Chinese (Simplified) - 简体中文"),
        ("zh-Hant", "Chinese (Traditional) - 繁體中文"),
        ("ja", "Japanese - 日本語"),
        ("ko", "Korean - 한국어"),
        ("es", "Spanish - Español"),
        ("fr", "French - Français"),
        ("de", "German - Deutsch"),
        ("ru", "Russian - Русский"),
    ]

    public static let defaultsKey = "BLInterfaceLanguage"

    /// The language chosen in Preferences ("" = Automatic: the iPad's, or the
    /// one set for this app in Settings).
    public static var chosen: String {
        get { UserDefaults.standard.string(forKey: defaultsKey) ?? "" }
        set { UserDefaults.standard.set(newValue, forKey: defaultsKey); load() }
    }

    /// The language the interface is in now. Observable: every view whose
    /// body looked text up reads it, so a change of language redraws exactly
    /// those, in place — nothing is rebuilt, no state is lost.
    public static var current: String { Observed.shared.code }

    @Observable
    final class Observed {
        nonisolated(unsafe) static let shared = Observed()
        var code = "en"
    }

    nonisolated(unsafe) private static var table: [String: String] = [:]
    nonisolated(unsafe) private static var patterns: [(regex: NSRegularExpression, translation: String)] = []
    nonisolated(unsafe) private static var resolved: [String: String] = [:]
    private static let lock = NSLock()

    /// The language Automatic stands for: the first of this app's
    /// localizations the system prefers (iPadOS applies Settings ▸ Blender
    /// Local ▸ Language here).
    static func automatic() -> String {
        let offered = languages.map(\.code).filter { !$0.isEmpty }
        return Bundle.preferredLocalizations(from: offered, forPreferences: Locale.preferredLanguages).first ?? "en"
    }

    /// Reads the chosen language's table. Called at launch and when the
    /// language changes (the root view is rebuilt then).
    public static func load() {
        let code = chosen.isEmpty ? automatic() : chosen
        var strings: [String: String] = [:]
        if code != "en",
           let path = Bundle.main.path(forResource: "Localizable", ofType: "strings", inDirectory: nil, forLocalization: code),
           let dict = NSDictionary(contentsOfFile: path) as? [String: String] {
            strings = dict
        }
        install(strings, code: code)
    }

    /// Makes `strings` the interface's table (the tests give their own).
    static func install(_ strings: [String: String], code: String) {
        var found: [(NSRegularExpression, String)] = []
        for (key, value) in strings where key.contains("%@") {
            let parts = key.components(separatedBy: "%@").map(NSRegularExpression.escapedPattern(for:))
            if let regex = try? NSRegularExpression(pattern: "^" + parts.joined(separator: "(.+?)") + "$",
                                                    options: [.dotMatchesLineSeparators]) {
                found.append((regex, value))
            }
        }
        // Longer patterns first: "Delete %@ objects" before "Delete %@".
        found.sort { $0.0.pattern.count > $1.0.pattern.count }
        lock.lock()
        table = strings
        patterns = found
        resolved = [:]
        lock.unlock()
        if Observed.shared.code != code { Observed.shared.code = code }
    }

    /// `text` in the interface language — Blender's `pgettext_iface`. Text
    /// with a value in it ("Added Cube") is matched against the table's
    /// patterns ("Added %@"), and the value itself is translated when the
    /// table knows it.
    public static func iface(_ text: String) -> String {
        if text.isEmpty { return text }
        _ = Observed.shared.code          // the view showing it redraws on a change of language
        lock.lock(); defer { lock.unlock() }
        if table.isEmpty { return text }
        if let t = table[text] { return t }
        if let t = resolved[text] { return t }
        let result = fill(text) ?? text
        if resolved.count > 4000 { resolved.removeAll(keepingCapacity: true) }
        resolved[text] = result
        return result
    }

    /// A datablock's name as Blender shows it: as it is, except the names
    /// Blender gives things that are not data (the Scene Collection,
    /// `BKE_collection_ui_name_get`), which it translates.
    public static func dataName(_ name: String) -> String {
        name == "Scene Collection" ? iface(name) : name
    }

    private static func fill(_ text: String) -> String? {
        guard text.count < 600, text.contains(where: { !$0.isWhitespace }) else { return nil }
        let range = NSRange(text.startIndex..., in: text)
        for (regex, translation) in patterns {
            guard let m = regex.firstMatch(in: text, range: range) else { continue }
            let values: [String] = (1..<m.numberOfRanges).map {
                let v = String(text[Range(m.range(at: $0), in: text)!])
                return table[v] ?? v
            }
            return substitute(translation, values)
        }
        return nil
    }

    /// Puts `values` into `format`'s `%@` (in order) and `%N$@` (by number).
    static func substitute(_ format: String, _ values: [String]) -> String {
        var out = ""
        var next = 0
        var i = format.startIndex
        while i < format.endIndex {
            let c = format[i]
            if c == "%" {
                let rest = format[format.index(after: i)...]
                if rest.hasPrefix("@") {
                    out += next < values.count ? values[next] : ""
                    next += 1
                    i = format.index(i, offsetBy: 2)
                    continue
                }
                let digits = rest.prefix { $0.isNumber }
                if !digits.isEmpty, rest.dropFirst(digits.count).hasPrefix("$@"), let n = Int(digits) {
                    out += n - 1 < values.count ? values[n - 1] : ""
                    i = format.index(i, offsetBy: 1 + digits.count + 2)
                    continue
                }
            }
            out.append(c)
            i = format.index(after: i)
        }
        return out
    }
}

// MARK: - SwiftUI, in the interface language

extension Text {
    /// Shown in the interface language. Names of data use `Text(verbatim:)`.
    init(_ content: String) {
        self.init(verbatim: Translation.iface(content))
    }
}

extension Button where Label == Text {
    init(_ title: String, action: @escaping () -> Void) {
        self.init(action: action) { Text(verbatim: Translation.iface(title)) }
    }

    init(_ title: String, role: ButtonRole?, action: @escaping () -> Void) {
        self.init(role: role, action: action) { Text(verbatim: Translation.iface(title)) }
    }
}

extension SwiftUI.Label where Title == Text, Icon == Image {
    init(_ title: String, systemImage: String) {
        self.init { Text(verbatim: Translation.iface(title)) } icon: { Image(systemName: systemImage) }
    }
}

extension Toggle where Label == Text {
    init(_ title: String, isOn: Binding<Bool>) {
        self.init(isOn: isOn) { Text(verbatim: Translation.iface(title)) }
    }
}

extension Section where Parent == Text, Content: View, Footer == EmptyView {
    init(_ title: String, @ViewBuilder content: () -> Content) {
        self.init(content: content, header: { Text(verbatim: Translation.iface(title)) })
    }
}

extension Menu where Label == Text, Content: View {
    init(_ title: String, @ViewBuilder content: () -> Content) {
        self.init(content: content, label: { Text(verbatim: Translation.iface(title)) })
    }
}

extension Picker where Label == Text, SelectionValue: Hashable, Content: View {
    init(_ title: String, selection: Binding<SelectionValue>, @ViewBuilder content: () -> Content) {
        self.init(selection: selection, content: content, label: { Text(verbatim: Translation.iface(title)) })
    }
}

extension TextField where Label == Text {
    init(_ title: String, text: Binding<String>) {
        self.init(text: text, prompt: nil, label: { Text(verbatim: Translation.iface(title)) })
    }
}

extension View {
    func navigationTitle(_ title: String) -> some View {
        navigationTitle(Text(verbatim: Translation.iface(title)))
    }

    func help(_ text: String) -> some View {
        help(Text(verbatim: Translation.iface(text)))
    }
}

extension CommandMenu {
    /// The menu bar's menus (the keyboard's ⌘ overlay on an iPad).
    init(_ name: String, @ViewBuilder content: () -> Content) {
        self.init(Text(verbatim: Translation.iface(name)), content: content)
    }
}
